head.script:
scwin.onpageload = function() {
    window.alert1Showed = false;
    window.alert2Showed = false;
    scwin.doInit();
}		
scwin.createWindow = function() {
    var c_cnt = 8;
    var c_subName = "windowContainer_tabmove_WPF-1518_(WSQ-2503)_sub";
    var c_xmlName = ".xml";
    for (var i = 0; i < c_cnt; i++) {
        windowContainer1.createWindow(c_subName + i, null, c_subName + i + c_xmlName, "", null, "existWindow", null, null);
    }
}
scwin.doInit = function() {
    this.createWindow();
}
scwin.windowContainer1_onafternamelayermove = function(info) {
    //alert("onafternamelayermove");
	alert1Showed = true;
    console.log(info)
}
scwin.windowContainer1_onbeforenamelayermove = function(info) {
    //alert("onbeforenamelayermove");
	alert2Showed = true;
    console.log(info)
}

	scwin.simulateWrapper = function(target, type, options) {
		WebSquare.wUnit.getJq(target).simulate(type, options);
	}
	scwin.setSimulate = function() {
		scwin.simulateWrapper('#windowContainer1_nameLayer_'+$p.id+'windowContainer1_subWindow7', 'drag-n-drop', {
			dx: -100,
			dy: 0
		});
	}

	scwin.checkVal = function() {
		return alert1Showed && alert2Showed;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "scwin.setSimulate()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");

		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}	
	scwin.unitTest()
